paired_cost.driver:
"""Paired consumer cost on synthetic data; run after correctness work is idle."""
from pathlib import Path
import hashlib,json,re,shutil,subprocess,time,statistics
BASE=Path(__file__).resolve().parent
WORK=BASE/'d099-cost'; WORK.mkdir(exist_ok=True)
COMPILER=BASE/'release/mmay'
roots={'before':BASE/'d099-notes-before','after':Path('/workspace/Projects/Marimay/marimay-notes')}
manifests={}
for phase,source in roots.items():
 target=WORK/phase; target.mkdir(exist_ok=True)
 files=[source/'mmay.mod',*source.glob('*.my'),*(source/'notes').glob('*.my'),*(source/'messages').glob('*.my')]
 manifests[phase]={}
 for file in files:
  name=file.relative_to(source);destination=target/name;destination.parent.mkdir(parents=True,exist_ok=True)
  shutil.copy2(file,destination);manifests[phase][str(name)]=hashlib.sha256(file.read_bytes()).hexdigest()
notes=[{'id':i,'text':'Синтетическая заметка 🌿 для проверки порядка и сохранности','tags':['проверка','язык']} for i in range(1,6099)]
def encode(notes): return json.dumps({'version':1,'nextId':6099,'notes':notes},ensure_ascii=False,separators=(',',':')).encode()
data=encode(notes)
assert len(data)==1047786 and hashlib.sha256(data).hexdigest()=='2c48707982e285d3253064a0c886224e5685b16aa07fcf4e8e353b84f6d2a3ad'
file=WORK/'working.json';engines={}
for phase in roots:
 folder=WORK/phase
 engines[phase]={'vm':[str(COMPILER),'run',str(folder),'--allow-read',str(WORK),'--allow-write',str(WORK),'--']}
 for profile in ('debug','release'):
  binary=WORK/f'{phase}-{profile}'
  command=[str(COMPILER),'build',str(folder),'--allow-read',str(WORK),'--allow-write',str(WORK),'--output',str(binary)]
  if profile=='release': command.append('--release')
  subprocess.run(command,check=True,capture_output=True,timeout=180)
  engines[phase][profile]=[str(binary)]
records=[]
cases=[('show-last',['show','6098'],f"#6098 {notes[-1]['text']} [проверка, язык]\n".encode(),data),
       ('remove-last',['remove','6098'],'Удалена заметка №6098.\n'.encode(),encode(notes[:-1]))]
for name,args,stdout,after in cases:
 for engine in ('vm','debug','release'):
  for repetition in range(4):
   phases=('before','after') if repetition%2==0 else ('after','before')
   for phase in phases:
    file.write_bytes(data)
    start=time.monotonic()
    result=subprocess.run(['/usr/bin/time','-l',*engines[phase][engine],'--db',str(file),*args],capture_output=True,timeout=120)
    elapsed=time.monotonic()-start
    assert result.returncode==0 and result.stdout==stdout,(name,phase,engine,result.returncode,result.stdout,result.stderr)
    assert file.read_bytes()==after,(name,phase,engine,'file mismatch')
    match=re.search(rb'^\s*(\d+)\s+maximum resident set size\s*$',result.stderr,re.M)
    assert match,result.stderr
    records.append({'case':name,'engine':engine,'phase':phase,'warmup':repetition==0,'wall_seconds':elapsed,
                    'peak_rss_bytes':int(match[1]),'after_sha256':hashlib.sha256(after).hexdigest()})
    print(name,engine,phase,repetition,round(elapsed,4),flush=True)
summary={}
for case,*_ in cases:
 summary[case]={}
 for engine in ('vm','debug','release'):
  summary[case][engine]={phase:{'median_seconds':statistics.median(r['wall_seconds'] for r in records if r['case']==case and r['engine']==engine and r['phase']==phase and not r['warmup']),
                               'median_peak_rss_bytes':statistics.median(r['peak_rss_bytes'] for r in records if r['case']==case and r['engine']==engine and r['phase']==phase and not r['warmup'])} for phase in roots}
report={'schema':'marimay.cp42.search-consumer-cost.v1','compiler_sha256':hashlib.sha256(COMPILER.read_bytes()).hexdigest(),
        'scope':'Small alternating paired warm-process sample, not cold-start or CP42 performance acceptance',
        'source_sha256':manifests,'dataset':{'notes':6098,'bytes':len(data),'sha256':hashlib.sha256(data).hexdigest()},
        'records':records,'summary':summary,'driver':Path(__file__).read_text()}
(WORK/'result.json').write_text(json.dumps(report,indent=2,ensure_ascii=False)+'\n')
print(json.dumps(summary,indent=2))
